parameters.jsCode:
// Verify the X-Hub-Signature-256 header before trusting anything.
//
// Meta signs every webhook with your app secret. Without this check, anyone
// who learns your webhook URL can post fake enquiries into your CRM and
// trigger outbound WhatsApp messages in your name.
//
// APP_SECRET must be set as an n8n environment variable.

const crypto = require('crypto');

const secret = $env.WHATSAPP_APP_SECRET;
if (!secret) {
  throw new Error('WHATSAPP_APP_SECRET is not set. Refusing to process unverified webhooks.');
}

const item = $input.first();
const headers = item.json.headers || {};
const signature = headers['x-hub-signature-256'] || '';

// rawBody comes through as a Buffer when the webhook node has rawBody enabled.
const raw = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body);

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');

const a = Buffer.from(signature);
const b = Buffer.from(expected);

if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Webhook signature did not verify. Dropping the request.');
}

return [{ json: typeof raw === 'string' ? JSON.parse(raw) : item.json.body }];

// Normalise the Meta payload into something the rest of the workflow can use.
//
// WhatsApp webhooks arrive for many reasons — delivery receipts, read receipts,
// status changes — and most of them are not a customer message. Filter early
// so nothing downstream has to guess.

const body = $input.first().json;
const out = [];

for (const entry of body.entry || []) {
  for (const change of entry.changes || []) {
    const value = change.value || {};

    // Statuses are delivery/read receipts, not messages. Ignore them.
    if (!value.messages) continue;

    const contactName = ((value.contacts || [])[0] || {}).profile?.name || '';

    for (const message of value.messages) {
      // Only handle text for now. Images, audio and location go to a human.
      const isText = message.type === 'text';

      out.push({
        json: {
          messageId: message.id,
          from: message.from,
          contactName,
          timestamp: Number(message.timestamp) * 1000,
          type: message.type,
          text: isText ? (message.text?.body || '') : '',
          needsHuman: !isText,
          phoneNumberId: value.metadata?.phone_number_id || ''
        }
      });
    }
  }
}

return out;

