parameters.jsCode:
// Parse the model's JSON and decide what happens next.
//
// Two rules that matter:
//  1. Never trust the model to return clean JSON. Strip fences, then try/catch.
//  2. Never let the model decide to quote a price. It extracts facts; a human
//     or your pricing engine decides money.

const response = $input.first().json;
const text = (response.content || [])
  .filter(block => block.type === 'text')
  .map(block => block.text)
  .join('')
  .replace(/```json|```/g, '')
  .trim();

let enquiry;
try {
  enquiry = JSON.parse(text);
} catch (err) {
  // Extraction failed. Do not guess — hand to a human.
  return [{
    json: {
      ...$('Normalise message').first().json,
      parseFailed: true,
      rawModelOutput: text,
      status: 'needs_human',
      missing: ['could not read the message']
    }
  }];
}

const REQUIRED = ['destination', 'travelDates', 'passengers'];
const missing = REQUIRED.filter(field => {
  const v = enquiry[field];
  return v === null || v === undefined || v === '' || v === 'unknown';
});

// Anything the model flagged as complex goes to a person regardless of
// how complete the extraction looks.
const complex = Boolean(enquiry.isComplex) || Boolean(enquiry.mentionsComplaint);

return [{
  json: {
    ...$('Normalise message').first().json,
    enquiry,
    missing,
    isComplete: missing.length === 0,
    status: complex ? 'needs_human' : (missing.length === 0 ? 'complete' : 'incomplete')
  }
}];

// Compose the reply.
//
// Deliberately templated rather than model-generated. A travel enquiry reply
// that invents a price, a policy or an availability claim is a liability, and
// a model asked to "be helpful" will do exactly that. The model's job in this
// workflow is extraction only.

const item = $input.first().json;
const config = $('Set config').first().json;
const enquiry = item.enquiry || {};

const QUESTIONS = {
  destination: 'where you would like to travel to',
  travelDates: 'roughly when you would like to travel',
  passengers: 'how many people are travelling'
};

let body;

if (item.status === 'complete') {
  const ref = 'ENQ-' + String(Date.now()).slice(-6);
  body = `Thanks${item.contactName ? ' ' + item.contactName.split(' ')[0] : ''}. `
       + `I have your enquiry for ${enquiry.destination}, `
       + `${enquiry.travelDates}, ${enquiry.passengers} travelling.\n\n`
       + `One of our consultants will come back to you with options `
       + `${config.responseTimePromise}.\n\n`
       + `Your reference is ${ref}.`;
  item.reference = ref;
} else {
  const asks = (item.missing || [])
    .map(field => QUESTIONS[field])
    .filter(Boolean);

  body = `Thanks for getting in touch. To put some options together I just need `
       + `${asks.length > 1 ? 'a couple of things' : 'one more thing'} — `
       + `${asks.join(', and ')}?`;
}

return [{ json: { ...item, replyText: body } }];

